import{_ as l,l as n,o as a,c as d,v as t,p as i,x as r,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"目标描述与 TableGen","description":"","frontmatter":{"title":"目标描述与 TableGen","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/target-description.md","filePath":"cs/target-description.md","lastUpdated":1789023840000}'),h={name:"cs/target-description.md"};function _(b,e,m,E,T,u){const o=n("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="目标描述与-tablegen" tabindex="-1">目标描述与 TableGen <a class="header-anchor" href="#目标描述与-tablegen" aria-label="Permalink to &quot;目标描述与 TableGen&quot;">​</a></h1><div class="epigraph"><p>把寄存器类、指令编码、选择模板写成声明式描述，生成选择器与汇编器，而不是为每个 opcode 手写一份 C。</p><footer>—— 据 LLVM TableGen 文档；GCC MD 机描述传统；Appel 对机器描述的讨论整理</footer></div><p>上一课<a href="/cs/tree-pattern-isel">树匹配</a>要大量模板。缺口是<strong>可维护的目标描述</strong>：LLVM TableGen（<code>.td</code>）、GCC <code>md</code>。本课钉描述驱动后端，不把 TableGen 语言当手册抄完。调用约定下一课再实现细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写 ISel 随 ISA 组合爆炸。描述：指令格式、约束、模式 <code>add r, r, r</code>。生成：匹配器、编码、反汇编。缺口是<strong>生成器链</strong>，不是 DP 方程。</p><p>寄存器类：GPR、FPR、约束子集（<code>x86</code> 的 <code>eax</code>）。描述错误则选择成功但编码错。</p><h3 id="td-不是源语言类型系统" tabindex="-1"><code>.td</code> 不是源语言类型系统 <a class="header-anchor" href="#td-不是源语言类型系统" aria-label="Permalink to &quot;`.td` 不是源语言类型系统&quot;">​</a></h3><p>它是编译器的 DSL。与<a href="/cs/dsl-embedding">DSL 嵌入</a> 后课对照：这里是编译器实现 DSL，不是用户程序 DSL。</p><p><span class="marginnote">LLVM TableGen。GCC 的 Define_Insn。本课不引用虚构论文号。工程文献以文档与源码为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写寄存器、指令、模式。跑 tblgen。检查：单测 MIR。增量：新指令加一条记录，不改匹配引擎。</p>',11)),(a(),i(p,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TD%5B%22%E7%9B%AE%E6%A0%87%E6%8F%8F%E8%BF%B0%22%5D%20--%3E%20GEN%5B%22tblgen%20%2F%20md%20%E7%94%9F%E6%88%90%22%5D%0A%20%20GEN%20--%3E%20ISEL%5B%22%E9%80%89%E6%8B%A9%E5%99%A8%20%2F%20%E7%BC%96%E7%A0%81%22%5D%0A%20%20ISEL%20--%3E%20ASM%5B%22%E6%B1%87%E7%BC%96%20%2F%20%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与调度：描述可含延迟与资源（itinerary），供表调度。缺模型则调度盲。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>生成代码巨大，编译编译器变慢。版本：描述与 LLVM 版本绑定。不要在 <code>.td</code> 里写任意副作用 C++ 还指望可证明。</p><p>交叉编译：同一描述可被不同主机的 tblgen 跑——后课三元组。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写调用约定 lowering 全文。后课默认：ISA 用描述生成后端。下一课调用约定实现：参数、返回、调用者保存如何从描述落到 lowering。</p><p>也不把 TableGen 当数据库 schema 课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>目标描述生成选择、编码、调度表。</li><li>TableGen/GCC MD 是声明式，减手写组合。</li><li>寄存器类与约束是一等公民。</li><li>出处：LLVM TableGen；GCC MD；对照 Aho 树匹配、Appel。</li></ul>',9))])}const g=l(h,[["render",_]]);export{A as __pageData,g as default};
